-- =============================================================================
-- English Lab - V14: seed masivo de actividades para los objetivos 1-3
-- Lleva PRON, BE y ART (A1) a 90 actividades NUEVAS cada uno (ids 121-390),
-- para que la practica libre de estos objetivos no repita siempre lo mismo.
-- level y skill son los del objetivo en V11 (A1, grammar); la categoria es la
-- misma que en V13 (PRON/BE -> 1 Verbo to be, ART -> 3 Articulos y adjetivos).
-- La clave sigue viviendo SOLO en el jsonb `content` (answer/accepted);
-- jamas viaja al navegador (el DTO de estudiante la omite).
-- Prompts unicos por objetivo: ninguno repite los de V11 ni los de V13.
-- =============================================================================

-- Las corridas de pruebas de integracion crean objetivos y actividades con ids
-- autoincrementales; en una base de pruebas reutilizada esas filas pueden ocupar
-- el rango 121-390 reservado aqui y romper la PK. Se liberan SOLO actividades de
-- prueba (objetivos fuera del seed 1-12; la API no permite crear objetivos, asi
-- que en produccion esta sentencia no borra nada). attempts/assignments caen en
-- cascada por sus FK.
delete from activities
where id between 121 and 390
  and objective_id not between 1 and 12;

insert into activities (id, objective_id, type, level, skill, title, content, category_id) overriding system value values

